"""Todd-Coxeter (HLT) for groups generated by involutions."""
def todd_coxeter(ngen, relators, maxcos=200000, subgens=()):
    # generators are involutions: table[c][g] = c', and table[c'][g] = c
    table = [[-1]*ngen]
    parent = [0]
    def find(c):
        while parent[c] != c:
            parent[c] = parent[parent[c]]; c = parent[c]
        return c
    queue = []
    def coincidence(a, b):
        q = [(a, b)]
        while q:
            a, b = q.pop()
            a, b = find(a), find(b)
            if a == b: continue
            if a > b: a, b = b, a
            parent[b] = a
            for g in range(ngen):
                t = table[b][g]
                if t == -1: continue
                t = find(t)
                ta = table[a][g]
                if ta == -1:
                    table[a][g] = t; table[t][g] = a
                else:
                    q.append((find(ta), t))
                table[b][g] = -1
    def define(c, g):
        n = len(table)
        if n >= maxcos: raise RuntimeError("too many cosets")
        table.append([-1]*ngen); parent.append(n)
        table[c][g] = n; table[n][g] = c
        return n
    def scan_and_fill(c, rel):
        # trace forward and backward, defining as needed
        while True:
            f = c; i = 0; n = len(rel)
            while i < n and table[f][rel[i]] != -1:
                f = find(table[f][rel[i]]); i += 1
            if i == n:
                if f != c: coincidence(f, c)
                return
            b = c; j = n - 1
            while j >= i and table[b][rel[j]] != -1:
                b = find(table[b][rel[j]]); j -= 1
            if j < i:
                coincidence(f, b); return
            if j == i:
                table[f][rel[i]] = b; table[b][rel[i]] = f
                return
            define(f, rel[i])
    for w in subgens:
        scan_and_fill(0, list(w))
    c = 0
    while c < len(table):
        if find(c) == c:
            for rel in relators:
                if find(c) != c: break
                scan_and_fill(c, rel)
            if find(c) == c:
                for g in range(ngen):
                    if table[c][g] == -1: define(c, g)
        c += 1
    return sum(1 for i in range(len(table)) if find(i) == i)
